init(seed, params) {
  const next = generator(seed);
  const x = [];
  for (let i = 0; i < MAXN; i++) {
    const v = new Float64Array(D);
    for (let d = 0; d < D; d++) v[d] = gauss(next);
    // sinusoidal position encoding, Eq. 3 of the paper
    for (let d = 0; d < D; d++) {
      const pos = i, k = Math.floor(d / 2);
      v[d] += d % 2 === 0 ? Math.sin(pos / Math.pow(10000, 2 * k / D)) : Math.cos(pos / Math.pow(10000, 2 * k / D));
    }
    normalize v;
    x.push(Array.from(v));
  }
  // per-head projections Wq, Wk, Wv: D x MAXK, sliced to keyDim at use time
  const W = [];
