    for (let i = 0; i < n; i += 1) concat.push(new Array(H * dk).fill(0));
    let rng = state.rng;
    for (let h = 0; h < H; h += 1) {
      const Q = [], K = [], V = [];
      for (let i = 0; i < n; i += 1) {
        Q.push(project(state.W[h].q, x[i], dk));
        K.push(project(state.W[h].k, x[i], dk));
        V.push(project(state.W[h].v, x[i], dk));
      }
      for (let i = 0; i < n; i += 1) {
        // dot-product scores, softmax (Eq. 1), then attention-weight dropout
        const s = new Array(n);
        let top = -Infinity;
        for (let j = 0; j < n; j += 1) {
          let d = 0;
          for (let c = 0; c < dk; c += 1) d += Q[i][c] * K[j][c];
          s[j] = d * scale;
          if (s[j] > top) top = s[j];
        }
        let z = 0;
        const w = new Array(n);
        for (let j = 0; j < n; j += 1) { w[j] = Math.exp(s[j] - top); z += w[j]; }
        for (let j = 0; j < n; j += 1) w[j] /= z;
        if (params.dropout > 0) {
          let live = 0;
          for (let j = 0; j < n; j += 1) {
            const r = rand(rng); rng = r[1];
            if (r[0] < params.dropout) w[j] = 0; else live += w[j];
          }
          for (let j = 0; j < n; j += 1) w[j] = live > 0 ? w[j] / live : 1 / n;
        }
        // head output goes into its slice of the concat vector (Eq. 2)
        for (let j = 0; j < n; j += 1) {
          attn[i][j] += w[j] / H;
          if (w[j] > 0) for (let c = 0; c < dk; c += 1) concat[i][h * dk + c] += w[j] * V[j][c];
        }
      }
    }
    for (let i = 0; i < n; i += 1) {
      // W^O maps the concat back to model width
      const out = new Array(D).fill(0);
      const m = H * dk, inv = 1 / Math.sqrt(m);
      for (let r = 0; r < m; r += 1) {
        const c = concat[i][r];
        if (c !== 0) for (let d = 0; d < D; d += 1) out[d] += c * state.WO[r][d] * inv;
      }
      // sublayer output plus a tiny FFN (Eq. 5), then the residual and normalisation
      // of section 3.1: x -> LayerNorm(x + Sublayer(x)), with a fixed step size.
      const u = new Array(D);
      let un = 0;
      for (let d = 0; d < D; d += 1) {
        u[d] = out[d] + 0.5 * Math.max(0, x[i][d] * state.f1[d]) * state.f2[d];
        un += u[d] * u[d];
      }
      un = Math.sqrt(un) || 1;
      let norm = 0;
      for (let d = 0; d < D; d += 1) { x[i][d] += (0.35 * u[d]) / un; norm += x[i][d] * x[i][d]; }
      norm = Math.sqrt(norm) || 1;
      for (let d = 0; d < D; d += 1) x[i][d] /= norm;
    }
    return { ...state, x, attn, rng, n, t: state.t + 1, params };
  },

  measure(state) {
    const n = state.n;
    if (!state.attn) return { entropy: Math.log2(n), focus: 1 / n, diversity: 1 };
    let ent = 0, focus = 0;
    for (let i = 0; i < n; i += 1) {
      let h = 0, mx = 0;
      for (let j = 0; j < n; j += 1) {
        const a = state.attn[i][j];
        if (a > 1e-12) h -= a * Math.log2(a);
        if (a > mx) mx = a;
      }
      ent += h; focus += mx;
    }
    // vectors are unit length, so cosine similarity is just the dot product
    let sim = 0, cnt = 0;
    for (let i = 0; i < n; i += 1) for (let j = i + 1; j < n; j += 1) {
      let d = 0;
      for (let c = 0; c < D; c += 1) d += state.x[i][c] * state.x[j][c];
      sim += d; cnt += 1;
    }
    return { entropy: ent / n, focus: focus / n, diversity: cnt ? Math.max(0, 1 - sim / cnt) : 0 };
  },

  frame(state) {
    const n = state.n;
    const towers = [], beams = [];
    for (let j = 0; j < n; j += 1) {
      let received = 0;
      for (let i = 0; i < n; i += 1) received += state.attn ? state.attn[i][j] : 1 / n;
      towers.push({ label: "token " + j, height: Math.min(1, (1.5 * received) / n), group: 0 });
    }
    if (state.attn) {
      for (let i = 0; i < n; i += 1) for (let j = 0; j < n; j += 1) {
        const w = state.attn[i][j];
        if (w > 1.5 / n) beams.push({ from: i, to: j, weight: Math.min(1, 2 * w), group: i === j ? 1 : 0 });
      }
    }
    return { towers, beams };
  },
};
